 body=boat_hero+f'''<div class="container">{boat_stats(key)}</div><section class="section"><div class="container boat-intro-grid"><div class="boat-intro-copy"><p class="eyebrow">Votre réception</p><h2>{'Un lieu vivant,<br><em>à votre image.</em>' if key=='florentine' else 'De l’espace,<br><em>pour vos idées.</em>'}</h2><p class="lead">{b['copy']}</p><p>Anniversaire, mariage, soirée privée ou événement d’entreprise : précisez votre date, vos horaires et le nombre d’invités. Nous étudions ensemble la configuration et les prestations adaptées.</p><p class="note">Les capacités sont communiquées à titre indicatif et confirmées selon l’aménagement de votre réception.</p></div><aside class="info-box"><h3>Les informations utiles</h3><p>{b['address']}</p><p><strong style="color:var(--ink)">{b['price']}</strong><br><span class="note">{'Hors options, selon la date et le créneau.' if key=='florentine' else 'Selon votre date, la durée et les prestations.'}</span></p><p class="note">{'Florentine reste à quai. Sonorisation et jeux de lumière sur place.' if key=='florentine' else 'Navigation, équipements et conditions à confirmer dans votre devis.'}</p><div class="button-row"><a class="btn" href="/devis-peniche.html?peniche={key}">Préparer mon événement</a><a class="btn secondary" href="/peniches.html#comparatif">Comparer les péniches</a></div></aside></div></section>'''
 if key=='florentine':body+='<section class="section venues"><div class="container"><div class="section-head"><div><p class="eyebrow">Découvrir les espaces</p><h2>Imaginez-vous ici.</h2></div><a class="small-link" href="/photos.html">Toutes les photos</a></div>'+gallery(5)+'</div></section>'+pricing()
 elif key=='alize':body+='<section class="section venues"><div class="container"><div class="section-head"><div><p class="eyebrow">Voir le lieu</p><h2>Découvrons Alizé ensemble.</h2><p>Les photos et les configurations de réception sont disponibles sur demande. Une visite permet de préciser les possibilités pour votre événement.</p></div><a class="btn secondary" href="'+wa('Bonjour, je souhaite recevoir les photos et les configurations de la péniche Alizé pour un événement.')+'" target="_blank" rel="noopener noreferrer">Demander les photos</a></div></div></section>'
 body+=faq()+contact()
 page(b['path'],'Privatiser '+b['name']+' à '+('Boulogne-Billancourt' if key=='florentine' else 'Paris-Bercy'),b['intro'],body,image=b['photo'] or '/logo-florentine.png')
